"""Saved-source pedestrian measurements for diagnostic compatibility.

Synthetic fixture values exercise source joins only. They cannot establish a
Native site, physical crossing, legal permission, or delivery acceptance.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from native_crossing import measure, verify_site


def required(root, name):
    path = root / name
    if not path.is_file() or path.is_symlink():
        raise ValueError('Missing required source: ' + name)
    return path


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def sources(root, names):
    return {name: sha(required(root, name)) for name in names}


def measure_signal(facts):
    rows = facts['measurements']
    return {'green_alone_frames': [r['frame'] for r in rows if r['green_alone']],
            'facing_head': True,
            'first_entry_frame': facts['first_highway_entry']['frame'] if facts['first_highway_entry'] else None}


def measure_crosswalk(facts):
    entry = facts['first_highway_entry']
    return {'kind': facts['crosswalk_kind'],
            'entry_inside_crosswalk': entry['in_crosswalk'] if entry else None,
            'highway_entry_frame': entry['frame'] if entry else None}


def measure_device(facts):
    rows = facts['measurements']
    return {'indications_by_frame': [{'frame': r['frame'],
                                       'indication': r['other_device_indication'],
                                       'mode': r['other_device_mode']}
                                      for r in rows],
            'entry_indication': facts['first_highway_entry']['other_device_indication']
                                if facts['first_highway_entry'] else None}


def build_report(root):
    root = Path(root).resolve()
    for name in ('map.json', 'head.json', 'devices.json', 'site.json', 'frames.json'):
        required(root, name)
    site = json.loads((root / 'site.json').read_text())
    verify_site(site, root)
    facts = measure(site, root, {'path': 'frames.json', 'sha256': sha(root / 'frames.json')})
    config = json.loads(required(root, 'config.json').read_text())
    suffix = config['selected_case_id'].split('__')[-1]
    expected = config['case']['scenario_parameters']
    entry = facts['first_highway_entry']
    if facts['crosswalk_kind'] != expected['crosswalk_kind']:
        raise ValueError('Diagnostic crosswalk kind differs from selected case')
    if (entry is not None) != expected['pedestrian_enters_highway']:
        raise ValueError('Diagnostic highway entry differs from selected case')
    if entry and entry['in_crosswalk'] != expected['entry_inside_crosswalk']:
        raise ValueError('Diagnostic crossing boundary differs from selected case')
    if any(r['other_device_indication'] != expected['other_device_indication'] for r in facts['measurements']):
        raise ValueError('Diagnostic device state differs from selected case')
    measurements = {
        'c111125_signal': {'method': 'measure_signal', 'value': measure_signal(facts),
                           'sources': sources(root, ('site.json', 'head.json', 'frames.json'))},
    }
    if suffix in ('marked_cross', 'unmarked_cross', 'outside_cross'):
        measurements['c111125_crosswalk'] = {
            'method': 'measure_crosswalk', 'value': measure_crosswalk(facts),
            'sources': sources(root, ('site.json', 'map.json', 'frames.json'))}
    if suffix in ('other_device_stop', 'other_device_cross'):
        measurements['c111125_other_device'] = {
            'method': 'measure_device', 'value': measure_device(facts),
            'sources': sources(root, ('site.json', 'devices.json', 'frames.json'))}
    return {'format': 'worker-analysis-report', 'case_id': config['selected_case_id'],
            'analysis_complete': True, 'measurements': measurements,
            'provenance_kind': 'synthetic_fixture', 'diagnostic_fixture': True,
            'legal_verdict_claimed': False, 'physical_acceptance_claimed': False,
            'limitations': ['Diagnostic fixture only; Native site, capture and legal assessment remain unverified.']}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    report = build_report(args.attempt)
    Path(args.output).write_text(json.dumps(report, indent=2, allow_nan=False) + '\n')


if __name__ == '__main__':
    main()

"""Portable authored pedestrian route control; observed movement is measured later."""
from __future__ import annotations
import math

ENTER_CASES = {'marked_cross', 'unmarked_cross', 'other_device_cross', 'outside_cross'}
WAIT_CASES = {'other_device_stop'}


def target_control(case_suffix, site, position_xy, control_factory, vector_factory, speed_mps=1.2):
    if case_suffix not in ENTER_CASES | WAIT_CASES:
        raise ValueError('unknown exact case')
    if not 0 < speed_mps <= 2.5:
        raise ValueError('speed outside authored pedestrian envelope')
    if case_suffix in WAIT_CASES:
        return control_factory(direction=vector_factory(0, 0, 0), speed=0, jump=False)
    x, y = map(float, position_xy)
    for goal in site['pedestrian_route_xy'][1:]:
        dx, dy = float(goal[0])-x, float(goal[1])-y
        norm = math.hypot(dx, dy)
        if norm > 0.25:
            return control_factory(direction=vector_factory(dx/norm, dy/norm, 0), speed=speed_mps, jump=False)
    return control_factory(direction=vector_factory(0, 0, 0), speed=0, jump=False)


def apply_case(actor, case_suffix, site, control_factory, vector_factory, speed_mps=1.2):
    loc = actor.get_location()
    command = target_control(case_suffix, site, (loc.x, loc.y), control_factory, vector_factory, speed_mps)
    actor.apply_control(command)
    return command


class RouteFollower:
    """Advance through route waypoints without steering back to a passed point."""

    def __init__(self, case_suffix, site, control_factory, vector_factory,
                 speed_mps=1.2, arrival_m=0.35):
        if case_suffix not in ENTER_CASES | WAIT_CASES:
            raise ValueError('unknown exact case')
        if not 0 < speed_mps <= 2.5 or not 0 < arrival_m <= 1:
            raise ValueError('invalid pedestrian controller setting')
        self.case_suffix = case_suffix
        self.route = site['pedestrian_route_xy']
        if len(self.route) < 3:
            raise ValueError('route requires start, crossing and destination')
        self.control_factory = control_factory
        self.vector_factory = vector_factory
        self.speed_mps = speed_mps
        self.arrival_m = arrival_m
        self.next_index = 1

    def apply(self, actor):
        loc = actor.get_location()
        x, y = float(loc.x), float(loc.y)
        if self.case_suffix in WAIT_CASES:
            speed, direction = 0, self.vector_factory(0, 0, 0)
        else:
            while self.next_index < len(self.route):
                gx, gy = map(float, self.route[self.next_index])
                if math.hypot(gx - x, gy - y) > self.arrival_m:
                    break
                self.next_index += 1
            if self.next_index == len(self.route):
                speed, direction = 0, self.vector_factory(0, 0, 0)
            else:
                gx, gy = map(float, self.route[self.next_index])
                dx, dy = gx - x, gy - y
                distance = math.hypot(dx, dy)
                speed = self.speed_mps
                direction = self.vector_factory(dx / distance, dy / distance, 0)
        command = self.control_factory(direction=direction, speed=speed, jump=False)
        actor.apply_control(command)
        return command

"""Independent source-bound comparison of crossing facts, not legal outcomes."""
from __future__ import annotations

PAIRS = {
    'marked_vs_unmarked': ('marked_cross', 'unmarked_cross', 'marked', 'unmarked', 'none', 'none', True, True),
    'contrary_device_choice': ('other_device_stop', 'other_device_cross', 'marked', 'marked', 'DONT_WALK', 'DONT_WALK', False, True),
    'crosswalk_boundary': ('marked_cross', 'outside_cross', 'marked', 'marked', 'none', 'none', True, False),
}


class ComparisonError(ValueError):
    pass


def audit_pair(comparison_id, left, right):
    if comparison_id not in PAIRS:
        raise ComparisonError('unknown comparison')
    ln, rn, lk, rk, ld, rd, le, re = PAIRS[comparison_id]
    if (left.get('case_suffix'), right.get('case_suffix')) != (ln, rn):
        raise ComparisonError('wrong exact cases')
    for key in ('map_source_sha256', 'signal_source_sha256', 'device_inventory_source_sha256',
                'highway_polygon_source_sha256', 'camera_profile_sha256', 'duration_frames'):
        if not left.get(key) or left[key] != right.get(key):
            raise ComparisonError('fixed condition differs: ' + key)
    for row, kind, device, entry, name in ((left, lk, ld, le, ln), (right, rk, rd, re, rn)):
        if row.get('crosswalk_kind') != kind:
            raise ComparisonError('crosswalk kind mismatch: ' + name)
        if row.get('green_alone_frames') != row['duration_frames']:
            raise ComparisonError('circular green alone not evidenced throughout: ' + name)
        observed = row.get('first_highway_entry')
        if (observed is not None) != entry:
            raise ComparisonError('highway entry mismatch: ' + name)
        if observed:
            if observed.get('other_device_indication') != device:
                raise ComparisonError('other device state mismatch: ' + name)
            if observed.get('in_crosswalk') is not (name != 'outside_cross'):
                raise ComparisonError('crosswalk location mismatch: ' + name)
        elif row.get('device_indication_while_waiting') != device:
            raise ComparisonError('device state while waiting mismatch: ' + name)
    return {'comparison_id': comparison_id, 'fixed_conditions_checked': 6,
            'legal_verdict': None, 'physical_acceptance': False}
